"""Tests for the ``on_startup_error`` callback parameter on ``FastAPI``."""

from __future__ import annotations

import pytest
from fastapi import FastAPI
from fastapi.testclient import TestClient


def test_startup_handler_error_propagates_by_default() -> None:
    """Without ``on_startup_error`` an exception raised in a startup handler
    must propagate normally and prevent the application from starting."""
    def bad_startup() -> None:
        raise RuntimeError("db unavailable")

    app = FastAPI(on_startup=[bad_startup])

    @app.get("/")
    def main() -> dict[str, str]:
        return {"message": "Hello World"}

    with pytest.raises(RuntimeError, match="db unavailable"):
        with TestClient(app):
            pytest.fail("TestClient should not have entered the context")


def test_startup_handler_error_caught_by_on_startup_error_callback() -> None:
    """When ``on_startup_error`` is provided, exceptions raised by startup
    handlers must be captured by the callback and startup must complete."""
    captured: list[Exception] = []

    def on_error(exc: Exception) -> None:
        captured.append(exc)

    def bad_startup() -> None:
        raise RuntimeError("db unavailable")

    app = FastAPI(on_startup=[bad_startup], on_startup_error=on_error)

    @app.get("/")
    def main() -> dict[str, str]:
        return {"message": "Hello World"}

    with TestClient(app) as client:
        # The error handler captured the exception, startup completed and the
        # application is fully functional.
        assert len(captured) == 1
        assert isinstance(captured[0], RuntimeError)
        assert str(captured[0]) == "db unavailable"

        response = client.get("/")
        assert response.status_code == 200, response.text
        assert response.json() == {"message": "Hello World"}


def test_startup_handler_error_propagates_when_on_startup_error_is_none() -> None:
    """Explicitly passing ``on_startup_error=None`` is equivalent to omitting
    the argument: the exception must propagate."""
    def bad_startup() -> None:
        raise RuntimeError("db unavailable")

    app = FastAPI(on_startup=[bad_startup], on_startup_error=None)

    @app.get("/")
    def main() -> dict[str, str]:
        return {"message": "Hello World"}

    with pytest.raises(RuntimeError, match="db unavailable"):
        with TestClient(app):
            pytest.fail("TestClient should not have entered the context")


def test_async_startup_handler_error_caught_by_on_startup_error_callback() -> None:
    """The callback should also intercept exceptions raised by async startup
    handlers, not only synchronous ones."""
    captured: list[Exception] = []

    def on_error(exc: Exception) -> None:
        captured.append(exc)

    async def bad_async_startup() -> None:
        raise ValueError("async failure")

    app = FastAPI(on_startup=[bad_async_startup], on_startup_error=on_error)

    @app.get("/")
    def main() -> dict[str, str]:
        return {"message": "Hello World"}

    with TestClient(app) as client:
        assert len(captured) == 1
        assert isinstance(captured[0], ValueError)
        assert str(captured[0]) == "async failure"

        response = client.get("/")
        assert response.status_code == 200, response.text


def test_multiple_startup_handlers_with_on_startup_error_continues_running() -> None:
    """If multiple startup handlers are registered and one of them raises, the
    remaining ones should still run and the application should still start."""
    captured: list[Exception] = []
    later_called: list[bool] = []

    def on_error(exc: Exception) -> None:
        captured.append(exc)

    def bad_startup() -> None:
        raise RuntimeError("db unavailable")

    def good_startup() -> None:
        later_called.append(True)

    app = FastAPI(
        on_startup=[bad_startup, good_startup],
        on_startup_error=on_error,
    )

    @app.get("/")
    def main() -> dict[str, str]:
        return {"message": "Hello World"}

    with TestClient(app) as client:
        assert len(captured) == 1
        assert isinstance(captured[0], RuntimeError)
        assert str(captured[0]) == "db unavailable"
        assert later_called == [True]

        response = client.get("/")
        assert response.status_code == 200, response.text
